import { EventEmitter } from 'node:events';

const orders = new EventEmitter();

orders.on('placed', (item, quantity) => {
  console.log(`Kitchen: prepare ${quantity} x ${item}`);
});

orders.once('placed', () => {
  console.log('Marketing: first order of the day!');
});

orders.emit('placed', 'coffee', 2);
orders.emit('placed', 'tea', 1);
console.log('Listeners left:', orders.listenerCount('placed'));

import { createReadStream } from 'node:fs';
import { createInterface } from 'node:readline';

const lines = createInterface({
  input: createReadStream('access.log'),
  crlfDelay: Infinity,
});

let total = 0;
let errors = 0;

for await (const line of lines) {
  total++;
  if (line.includes(' 500 ')) errors++;
}

console.log(`${total} requests, ${errors} server errors`);

import { createReadStream, createWriteStream } from 'node:fs';
import { createGzip } from 'node:zlib';
import { pipeline } from 'node:stream/promises';

await pipeline(
  createReadStream('access.log'),
  createGzip(),
  createWriteStream('access.log.gz'),
);

console.log('Compressed access.log to access.log.gz');

import { Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';

const shout = new Transform({
  transform(chunk, encoding, callback) {
    callback(null, chunk.toString().toUpperCase());
  },
});

await pipeline(process.stdin, shout, process.stdout);

